    if (timeUtcEl) {
      timeUtcEl.textContent = `${hours}:${minutes}:${seconds}`;
    }
  }

  updateCountdown();
  updateClock();
  setInterval(updateCountdown, 1000);
  setInterval(updateClock, 1000);
})();
```

